from collections import deque

def shortest_path(graph, source, target):
    # If the source is the same as the target, the path is trivial and distance is 0
    if source == target:
        return (0, [source])

    # Initialize distances and paths
    distances = {node: float('inf') for node in graph}
    distances[source] = 0
    paths = {node: [] for node in graph}

    # Queue for BFS
    queue = deque([source])

    while queue:
        current_node = queue.popleft()

        # Iterate through neighbors
        for neighbor, weight in graph.get(current_node, []):
            if distances[neighbor] > distances[current_node] + weight:
                distances[neighbor] = distances[current_node] + weight
                paths[neighbor] = paths[current_node] + [neighbor]

                # If we've found the target, return the path and distance
                if neighbor == target:
                    return (distances[neighbor], paths[neighbor])

                queue.append(neighbor)

    # If target is unreachable, return infinity and None
    return (float('inf'), None)
