def shortest_path(graph, source, target):
    from heapq import heappush, heappop
    from math import inf

    if not graph:
        return (inf, None)

    # Initialize the priority queue with the source node
    priority_queue = [(0, source)]
    # Initialize the parent pointers for the path reconstruction
    parents = {source: None}
    # Initialize the distance dictionary to track the shortest distance to each node
    distances = {node: inf for node in graph}
    distances[source] = 0

    while priority_queue:
        current_distance, current_node = heappop(priority_queue)

        if current_node == target:
            # Reconstruct the path from the target to the source using the parent pointers
            path = []
            while current_node is not None:
                path.insert(0, current_node)
                current_node = parents[current_node]
            return (current_distance, path)

        # Explore neighbors
        for neighbor, weight in graph.get(current_node, []):
            distance = current_distance + weight

            if distance < distances[neighbor]:
                # Update the distance and the parent pointer
                distances[neighbor] = distance
                parents[neighbor] = current_node
                # Add the neighbor to the priority queue
                heappush(priority_queue, (distance, neighbor))

    # If we reach here, it means the target is unreachable
    return (inf, None)
