import heapq

def shortest_path(graph, source, target):
    # Initialize the heap with source node
    heap = [(0, [source])]
    visited = set()

    while heap:
        (dist, path) = heapq.heappop(heap)
        node = path[-1]

        if node == target:
            return (dist, path)

        if node in visited:
            continue
        visited.add(node)

        for neighbor, weight in graph.get(node, []):
            if neighbor not in visited:
                heapq.heappush(heap, (dist + weight, path + [neighbor]))

    # If target is unreachable
    return (float("inf"), None)

