def shortest_path(graph, source, target):
    from heapq import heappush, heappop

    def calculate_distance(graph, source, target):
        distances = {node: float('inf') for node in graph}
        distances[source] = 0
        queue = [(0, source)]
        while queue:
            current_distance, current_node = heappop(queue)
            if current_node == target:
                return distances[target]
            for neighbor, weight in graph.get(current_node, []):
                distance = current_distance + weight
                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    heappush(queue, (distance, neighbor))
        return distances[target] if distances[target] != float('inf') else -1

    def reconstruct_path(graph, source, target, distances, parents):
        path = []
        current_node = target
        while current_node != source:
            path.append(current_node)
            current_node = parents[current_node]
        path.append(source)
        path.reverse()
        return path

    distances = calculate_distance(graph, source, target)
    if distances == float('inf'):
        return float('inf'), None
    parents = {source: source}
    current_node = target
    while current_node != source:
        for neighbor, _ in graph.get(current_node, []):
            if distances[neighbor] == distances[current_node] + 1:
                parents[neighbor] = current_node
                current_node = neighbor
                break
    return distances, reconstruct_path(graph, source, target, distances, parents)

