def shortest_path(graph, source, target):
    # We start by initializing the previous node dictionary to keep track of the path
    previous = {node: None for node in graph}
    # And the unvisited nodes dictionary to keep track of the distance to each node
    unvisited = {node: float('inf') for node in graph}
    unvisited[source] = 0

    # We use a priority queue to always expand the least cost node first
    from heapq import heappush, heappop
    priority_queue = [(0, source)]

    while priority_queue:
        current_distance, current_node = heappop(priority_queue)

        # If we've reached the target, we can stop the algorithm
        if current_node == target:
            reconstructed_path = []
            while current_node is not None:
                reconstructed_path.append(current_node)
                current_node = previous[current_node]
            return (current_distance, list(reversed(reconstructed_path)))

        # If we've exhausted the neighbors of the current node, we skip it
        if current_node not in graph:
            continue

        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight

            # If we've found an even shorter path to the neighbor, we update the distance and change the previous node
            if distance < unvisited[neighbor]:
                unvisited[neighbor] = distance
                previous[neighbor] = current_node
                heappush(priority_queue, (distance, neighbor))

    # If we've exhausted all the paths and haven't found the target, it's unreachable
    return (float('inf'), None)
